"""ONNX Runtime parity harness: golden reference vs ONNX, same numbers.

Runs block-by-block with explicit state feedback against the golden vectors
generated by make_golden.py (from the wrappers, which are proven bit-exact
against the stock TorchScript export by test_rebuild + test_stateful_eager).
"""
import json
import time
from pathlib import Path

import numpy as np
import onnxruntime as ort

HERE = Path(__file__).resolve().parent
META = json.loads((HERE / "models" / "rave_meta.json").read_text())
G = np.load(HERE / "golden" / "golden.npz")
BLOCK = int(G["block_size"])
N_BLOCKS = int(G["n_blocks"])
N_FRAMES = int(G["n_frames"])
TOL = 1e-5


def session(name):
    return ort.InferenceSession(str(HERE / "models" / name),
                                providers=["CPUExecutionProvider"])


def report(name, ref, out, tol=TOL):
    ref, out = np.asarray(ref), np.asarray(out)
    diff = np.abs(ref - out).max()
    scaled = diff / (1.0 + np.abs(ref).max())
    status = "OK " if scaled < tol else "FAIL"
    print(f"[{status}] {name:<46} max diff {diff:.3e} "
          f"(scaled {scaled:.3e}, tol {tol:g})")
    assert scaled < tol, name


def audio_block(arr, i):
    return arr[..., i * BLOCK:(i + 1) * BLOCK]


def run_forward(sess, audio, fills, state=None):
    state = np.zeros((1, META["state_sizes"]["forward"]), np.float32) \
        if state is None else state
    out = []
    for i in range(N_BLOCKS):
        y, state = sess.run(None, {"audio_in": audio_block(audio, i),
                                   "state_in": state,
                                   "fill_in": fills[i]})
        out.append(y)
    return np.concatenate(out, -1), state


def main():
    sess_fwd = session("rave_forward.onnx")
    sess_enc = session("rave_encoder.onnx")
    sess_dec = session("rave_decoder.onnx")

    out, _ = run_forward(sess_fwd, G["audio"], G["fill_fwd"])
    report("forward: onnxruntime vs golden", G["forward_ref"], out)

    state = np.zeros((1, META["state_sizes"]["encoder"]), np.float32)
    z_out = []
    for i in range(N_BLOCKS):
        z, state = sess_enc.run(None, {"audio_in": audio_block(G["audio"], i),
                                       "state_in": state})
        z_out.append(z)
    report("encoder: onnxruntime vs golden", G["latent_ref"],
           np.concatenate(z_out, -1))

    state = np.zeros((1, META["state_sizes"]["decoder"]), np.float32)
    y_out = []
    for i in range(N_BLOCKS):
        z = G["latent_ref"][..., i * N_FRAMES:(i + 1) * N_FRAMES]
        y, state = sess_dec.run(None, {"latent_in": z, "state_in": state,
                                       "fill_in": G["fill_dec"][i]})
        y_out.append(y)
    report("decoder: onnxruntime vs golden", G["decoder_ref"],
           np.concatenate(y_out, -1))

    # statelessness: interleave two streams through ONE session
    sa = np.zeros((1, META["state_sizes"]["forward"]), np.float32)
    sb = np.zeros((1, META["state_sizes"]["forward"]), np.float32)
    out_a, out_b = [], []
    for i in range(N_BLOCKS):
        ya, sa = sess_fwd.run(None, {"audio_in": audio_block(G["audio"], i),
                                     "state_in": sa, "fill_in": G["fill_fwd"][i]})
        yb, sb = sess_fwd.run(None, {"audio_in": audio_block(G["audio_b"], i),
                                     "state_in": sb,
                                     "fill_in": G["fill_fwd_b"][i]})
        out_a.append(ya)
        out_b.append(yb)
    report("interleaved stream A (one session)", G["forward_ref"],
           np.concatenate(out_a, -1))
    report("interleaved stream B (one session)", G["forward_ref_b"],
           np.concatenate(out_b, -1))

    # reproducibility across sessions
    out2, _ = run_forward(session("rave_forward.onnx"), G["audio"],
                          G["fill_fwd"])
    report("fresh session bit-identical", out, out2, tol=1e-12)

    # benchmark
    state = np.zeros((1, META["state_sizes"]["forward"]), np.float32)
    chunk = audio_block(G["audio"], 0)
    fill = G["fill_fwd"][0]
    for _ in range(5):
        sess_fwd.run(None, {"audio_in": chunk, "state_in": state,
                            "fill_in": fill})
    t0 = time.perf_counter()
    n_iter = 200
    for _ in range(n_iter):
        _, state = sess_fwd.run(None, {"audio_in": chunk, "state_in": state,
                                       "fill_in": fill})
    dt = (time.perf_counter() - t0) / n_iter * 1000
    budget = BLOCK / META["sample_rate"] * 1000
    print(f"\nbenchmark: {dt:.2f} ms per {BLOCK}-sample block "
          f"(realtime budget {budget:.2f} ms, {budget / dt:.1f}x realtime)")
    print("ALL OK")


if __name__ == "__main__":
    main()
